@media(max-width:520px){.proc-grid{grid-template-columns:1fr}}

/* industries */
.ind-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(172px,1fr));gap:12px}
.ind-t{flex:1 1 auto;min-width:0;overflow-wrap:normal;line-height:1.2}
.ind{display:flex;align-items:center;gap:11px;background:var(--glass);border:1px solid var(--line);
  border-radius:13px;padding:14px 15px;font-family:var(--fdisp);font-weight:600;font-size:.94rem;transition:.16s;backdrop-filter:blur(10px)}
.ind:hover{border-color:var(--cyan);transform:translateY(-3px);box-shadow:0 0 24px -8px var(--gcyan)}
.ind .ii{width:34px;height:34px;border-radius:9px;background:rgba(247,168,10,.12);border:1px solid var(--line2);display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:.16s}
.ind:hover .ii{background:linear-gradient(135deg,var(--cyan),var(--violet))}
