.plan.pop{border:1px solid rgba(247,168,10,.5);box-shadow:0 0 40px -14px rgba(247,168,10,.5),0 0 60px -20px var(--gviolet);background:linear-gradient(180deg,rgba(247,168,10,.08),rgba(247,168,10,.05))}
.plan .pop-tag{position:absolute;top:-13px;left:50%;transform:translateX(-50%);background:linear-gradient(120deg,#ffc247,#f7a80a);
  color:#231704;font-family:var(--fdisp);font-weight:800;font-size:.72rem;letter-spacing:.06em;padding:5px 14px;border-radius:999px;box-shadow:0 0 20px -6px rgba(247,168,10,.6)}
.plan{overflow:visible}
